types.text:
interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

interface MuxUITableColumn extends MuxUICollectionItem {
  isRowHeader?: boolean;
  sortable?: boolean;
}

interface MuxUITableRow extends MuxUICollectionItem {
  values?: Record<string, React.ReactNode>;
}

type TableOwnProps = {
  columns?: MuxUITableColumn[];
  rows?: MuxUITableRow[];
  selectedIds?: MuxUISelection;
  defaultSelectedIds?: MuxUISelection;
  sortDescriptor?: MuxUITableSortDescriptor;
  disabled?: boolean;
  selectionMode?: 'none' | 'single' | 'multiple';
  onSelectionChange?: (ids: MuxUISelection) => void;
  onRowAction?: (row?: MuxUITableRow) => void;
  onSortChange?: (next: MuxUITableSortDescriptor) => void;
};

type TableProps = MuxUIAriaLabel & TableOwnProps & {
  className?: string;
};
